begin;
create extension if not exists pgtap with schema extensions;
select plan(35);
insert into public.work_cards(company_id,stage_id,title,next_actor) select company_id,id,'Skills run A','30000000-0000-0000-0000-000000000001' from public.work_stages where company_id='10000000-0000-0000-0000-000000000001' and position=1;
insert into public.work_cards(company_id,stage_id,title,next_actor) select company_id,id,'Skills run B','30000000-0000-0000-0000-000000000001' from public.work_stages where company_id='10000000-0000-0000-0000-000000000001' and position=1;
select set_config('test.card_a',(select id::text from public.work_cards where title='Skills run A'),true);
select set_config('test.card_b',(select id::text from public.work_cards where title='Skills run B'),true);
-- Skill loads belong to runs: run keys of the Writer for card A (a1) and card B (a3), an expired one (a4), a company key (a5) and the Designer's run key (a2).
insert into public.agent_keys(id,company_id,person_id,key_hash,kind,card_id,expires_at) values
 ('b0000000-0000-0000-0000-0000000000a1','10000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','skills-writer-run-a','run',current_setting('test.card_a')::bigint,now()+interval '1 hour'),
 ('b0000000-0000-0000-0000-0000000000a3','10000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','skills-writer-run-b','run',current_setting('test.card_b')::bigint,now()+interval '1 hour'),
 ('b0000000-0000-0000-0000-0000000000a4','10000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','skills-writer-run-expired','run',current_setting('test.card_a')::bigint,now()+interval '1 hour'),
 ('b0000000-0000-0000-0000-0000000000a2','10000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000002','skills-designer-run','run',current_setting('test.card_a')::bigint,now()+interval '1 hour');
insert into public.agent_keys(id,company_id,person_id,key_hash) values ('b0000000-0000-0000-0000-0000000000a5','10000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','skills-writer-company-key');
update public.agent_keys set expires_at=now()-interval '1 second' where id='b0000000-0000-0000-0000-0000000000a4';
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000004',true);
select is((public.install_skill('10000000-0000-0000-0000-000000000001','library',E'---\nname: caption-hooks\ndescription: Write hooks\npermissions: cards.read\n---\nOpen with the reader''s problem.')->>'version')::int,1,'any team member, even a viewer, installs a skill');
select is(public.install_skill('10000000-0000-0000-0000-000000000001','upload',E'---\nname: shady\ndescription: Runs on install\npostinstall: ./setup.sh\npermissions: none\n---\nBody')->'refused','["install_script"]'::jsonb,'a skill with an install script is refused with the reason');
select is(public.install_skill('10000000-0000-0000-0000-000000000001','upload',E'---\nname: no-permissions\ndescription: Declares nothing\n---\nBody')->'refused','["no_permissions"]'::jsonb,'a skill that declares no permissions is refused');
select is(public.install_skill('10000000-0000-0000-0000-000000000001','upload',E'---\nname: huge\ndescription: Too big\npermissions: none\n---\n'||repeat('x',20001))->'refused','["too_large"]'::jsonb,'a skill over the size limit is refused');
select is((select count(*)::int from public.skills where company_id='10000000-0000-0000-0000-000000000001'),1,'refused skills are not stored');
select is((public.install_skill('10000000-0000-0000-0000-000000000001','library',E'---\nname: caption-hooks\ndescription: Write hooks\npermissions: cards.read\n---\nOpen with the reader''s problem.')->>'version')::int,1,'installing the same content again changes nothing');
select is((public.install_skill('10000000-0000-0000-0000-000000000001','team',E'---\nname: caption-hooks\ndescription: Write hooks\npermissions: cards.read\n---\nOpen with the reader''s problem, then the proof.')->>'version')::int,2,'new content makes a new version');
select throws_ok($$select public.install_skill('10000000-0000-0000-0000-000000000003','library',E'---\nname: x\ndescription: x\npermissions: none\n---\nB')$$,'42501',null,'a person outside the company cannot install');
select throws_ok($$insert into public.skills(company_id,slug,source) values ('10000000-0000-0000-0000-000000000001','direct','upload')$$,'42501',null,'clients cannot write skills directly');
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000001',true);
select throws_ok($$select public.install_skill('10000000-0000-0000-0000-000000000001','library',E'---\nname: x\ndescription: x\npermissions: none\n---\nB')$$,'42501',null,'an agent cannot install a skill');
select throws_ok($$select public.set_skill_enabled('10000000-0000-0000-0000-000000000001',(select id from public.skills limit 1),'30000000-0000-0000-0000-000000000001',true)$$,'42501',null,'an agent cannot enable a skill for itself');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
select lives_ok($$select public.set_skill_enabled('10000000-0000-0000-0000-000000000001',(select id from public.skills where slug='caption-hooks'),'30000000-0000-0000-0000-000000000001',true)$$,'the owner enables the skill for the Writer');
select throws_ok($$select public.set_skill_enabled('10000000-0000-0000-0000-000000000003',(select id from public.skills where slug='caption-hooks'),'30000000-0000-0000-0000-000000000001',true)$$,null,'skill not found','a skill of RS cannot be enabled in Aleem');
select set_config('request.jwt.claims','',true);
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claims',json_build_object('sub','30000000-0000-0000-0000-000000000001','role','authenticated','run_card',current_setting('test.card_a')::bigint)::text,true);
select is((select count(*)::int from jsonb_array_elements(public.agent_load_skills('10000000-0000-0000-0000-000000000001','b0000000-0000-0000-0000-0000000000a1'))),1,'the Writer reads exactly its enabled skills');
select is((public.agent_load_skills('10000000-0000-0000-0000-000000000001','b0000000-0000-0000-0000-0000000000a1')->0->>'version')::int,2,'the agent gets the latest stored version');
select throws_ok($$select public.agent_load_skills('10000000-0000-0000-0000-000000000001','b0000000-0000-0000-0000-0000000000a2')$$,'42501',null,'an agent cannot read through another agent key');
select is((select count(*)::int from public.skill_loads where key_id='b0000000-0000-0000-0000-0000000000a1' and version=2 and slug='caption-hooks'),1,'the load is recorded against the key with the version');
select throws_ok($$select public.agent_load_skills('10000000-0000-0000-0000-000000000001','b0000000-0000-0000-0000-0000000000a5')$$,'42501',null,'a company key is not a run: it reads no skills');
select throws_ok($$select public.agent_load_skills('10000000-0000-0000-0000-000000000001','b0000000-0000-0000-0000-0000000000a4')$$,'42501',null,'an expired run key reads no skills');
select throws_ok($$select public.agent_load_skills('10000000-0000-0000-0000-000000000001','b0000000-0000-0000-0000-0000000000a3')$$,'42501',null,'a run key of another card is refused when the token names this card');
select set_config('request.jwt.claims','',true);
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
select is((public.install_skill('10000000-0000-0000-0000-000000000001','team',E'---\nname: caption-hooks\ndescription: Write hooks\npermissions: cards.read\n---\nOpen with the reader''s problem, then the proof, then one ask.')->>'version')::int,3,'a third version is stored for the next run');
select set_config('request.jwt.claims','',true);
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claims',json_build_object('sub','30000000-0000-0000-0000-000000000001','role','authenticated','run_card',current_setting('test.card_b')::bigint)::text,true);
select is((public.agent_load_skills('10000000-0000-0000-0000-000000000001','b0000000-0000-0000-0000-0000000000a3')->0->>'version')::int,3,'a second run of the Writer gets the new version');
select is((select count(*)::int from public.skill_loads where key_id='b0000000-0000-0000-0000-0000000000a1'),1,'the first run still shows one load');
select is((select version from public.skill_loads where key_id='b0000000-0000-0000-0000-0000000000a1'),2,'the first run keeps the version it loaded');
select is((select version from public.skill_loads where key_id='b0000000-0000-0000-0000-0000000000a3'),3,'two run keys keep separate histories');
select set_config('request.jwt.claims','',true);
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000002',true);
select set_config('request.jwt.claims',json_build_object('sub','30000000-0000-0000-0000-000000000002','role','authenticated','run_card',current_setting('test.card_a')::bigint)::text,true);
select is(public.agent_load_skills('10000000-0000-0000-0000-000000000001','b0000000-0000-0000-0000-0000000000a2'),'[]'::jsonb,'the Designer, with nothing enabled, loads nothing');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
select lives_ok($$select public.set_skill_enabled('10000000-0000-0000-0000-000000000001',(select id from public.skills where slug='caption-hooks'),'30000000-0000-0000-0000-000000000001',false)$$,'the owner disables it again');
select set_config('request.jwt.claims','',true);
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claims',json_build_object('sub','30000000-0000-0000-0000-000000000001','role','authenticated','run_card',current_setting('test.card_a')::bigint)::text,true);
select is(public.agent_load_skills('10000000-0000-0000-0000-000000000001','b0000000-0000-0000-0000-0000000000a1'),'[]'::jsonb,'a disabled skill is no longer read');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
select is((select count(*)::int from public.skill_events where action='install'),3,'every stored install is recorded');
select is((select count(*)::int from public.skill_events where action in ('enable','disable') and actor_id='20000000-0000-0000-0000-000000000001'),2,'enable and disable are recorded with the acting person');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000002',true);
select is((select count(*)::int from public.skills where company_id<>'10000000-0000-0000-0000-000000000001'),0,'a member sees no skills of another company');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
select lives_ok($$select public.set_skill_enabled('10000000-0000-0000-0000-000000000001',(select id from public.skills where slug='caption-hooks'),'30000000-0000-0000-0000-000000000001',true)$$,'the owner enables it again');
select is((select count(*)::int from public.skill_agents('10000000-0000-0000-0000-000000000001') where role='writer'),1,'the agents to enable for come from the active grants');
select public.revoke_agent_access('10000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001');
select is((select count(*)::int from public.skill_agents('10000000-0000-0000-0000-000000000001') where role='writer'),0,'a revoked agent is no longer offered');
select set_config('request.jwt.claims','',true);
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claims',json_build_object('sub','30000000-0000-0000-0000-000000000001','role','authenticated','run_card',current_setting('test.card_a')::bigint)::text,true);
select throws_ok($$select public.agent_load_skills('10000000-0000-0000-0000-000000000001','b0000000-0000-0000-0000-0000000000a1')$$,'42501',null,'a revoked agent cannot read skills even by calling the database directly with its key');
select * from finish();
rollback;
